#include <iostream>
#include <vector>
#include <string>
#include <queue>

using namespace std;

int main() {
    // Otimização de I/O
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<string> grid(n);
    queue<pair<int, int>> q;

    for (int i = 0; i < n; ++i) {
        cin >> grid[i];
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'o') {
                q.push({i, j});
            }
        }
    }

    while (!q.empty()) {
        auto [r, c] = q.front();
        q.pop();

        // A água escorre verticalmente para baixo
        if (r + 1 < n && grid[r + 1][c] == '.') {
            grid[r + 1][c] = 'o';
            q.push({r + 1, c});
        }

        // Se abaixo houver uma prateleira, a água escorre horizontalmente
        if (r + 1 < n && grid[r + 1][c] == '#') {
            if (c - 1 >= 0 && grid[r][c - 1] == '.') {
                grid[r][c - 1] = 'o';
                q.push({r, c - 1});
            }
            if (c + 1 < m && grid[r][c + 1] == '.') {
                grid[r][c + 1] = 'o';
                q.push({r, c + 1});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        cout << grid[i] << "\n";
    }

    return 0;
}
